import android.graphics.drawable.Drawable;
import androidx.annotation.Nullable;
import androidx.fragment.app.FragmentActivity;

import net.osmand.plus.R;
import net.osmand.plus.chooseplan.button.PriceButton;
import net.osmand.plus.chooseplan.button.PriceButtonsUtils;
import net.osmand.plus.inapp.InAppPurchases;
import net.osmand.plus.inapp.InAppPurchases.InAppSubscription;

import java.util.ArrayList;
import java.util.List;

public class SubscriptionFragment extends FragmentActivity {

    @Override
    protected void initData(@Nullable Bundle args) {
    }

    @Override
    protected void collectPriceButtons(List<PriceButton<?>> priceButtons) {
        priceButtons.clear();
        priceButtons.addAll(PriceButtonsUtils.collectSubscriptions(app, purchaseHelper, getVisibleSubscriptions()));
    }

    @Override
    protected int getTitleStringId() {
        return R.string.choose_plan;
    }

    @Override
    protected int getHeaderIconId() {
        return R.drawable.ic_os_subscription;
    }

    @Override
    protected List<InAppSubscription> getVisibleSubscriptions() {
        InAppPurchases purchases = app.getInAppPurchaseHelper().getInAppPurchases();
        List<InAppSubscription> subscriptions = new ArrayList<>();
        List<InAppSubscription> visibleSubscriptions = purchaseHelper.getSubscriptions().getVisibleSubscriptions();
        filterVisibleSubscriptions(subscriptions, visibleSubscriptions, purchases);
        return subscriptions;
    }

    private void filterVisibleSubscriptions(List<InAppSubscription> subscriptions, 
                                            List<InAppSubscription> visibleSubscriptions, 
                                            InAppPurchases purchases) {
        for (InAppSubscription subscription : visibleSubscriptions) {
            if (!purchases.isPurchased(subscription.getSku()) && !purchases.isTrialPurchased(subscription.getSku())) {
                subscriptions.add(subscription);
            }
        }
    }

    @Override
    protected Drawable getPreviewListCheckmark() {
        return getCheckmark();
    }
}
```

In this refactoring, the logic for filtering visible subscriptions that aren't purchased or aren't in a trial is moved to a new method `filterVisibleSubscriptions`. This enhances the clarity of the `getVisibleSubscriptions` method, making the overall code cleaner and more maintainable.

