```java
public class SSTableNamesIterator extends SimpleAbstractColumnIterator {
    private ColumnFamily cf;
    private Iterator<IColumn> iter;
    public final SortedSet<byte[]> columns;
    private final DecoratedKey decoratedKey; // Re-add this since it was removed

    public SSTableNamesIterator(SSTableReader ssTable, DecoratedKey key, SortedSet<byte[]> columnNames) {
        this(ssTable, null, key, columnNames);
    }

    public SSTableNamesIterator(SSTableReader sstable, FileDataInput file, DecoratedKey key, SortedSet<byte[]> columnNames) {
        boolean closeFileWhenDone = (file == null);

        try {
            assert columnNames != null;
            this.columns = columnNames;
            this.decoratedKey = key;

            if (file == null) {
                file = openSSTableFile(sstable);
            }

            if (file == null) {
                return;
            }

            readColumnFamily(sstable, file, columnNames);

        } catch (IOException ioe) {
            throw new IOError(ioe);
        } finally {
            if (closeFileWhenDone) {
                closeFile(file);
            }
        }
    }

    private FileDataInput openSSTableFile(SSTableReader sstable) throws IOException {
        FileDataInput file = sstable.getFileDataInput(decoratedKey, DatabaseDescriptor.getIndexedReadBufferSizeInKB() * 1024);
        if (file == null) {
            return null;
        }
        DecoratedKey keyInDisk = SSTableReader.decodeKey(sstable.getPartitioner(), sstable.getDescriptor(), FBUtilities.readShortByteArray(file));
        assert keyInDisk.equals(decoratedKey) : String.format("%s != %s", keyInDisk, decoratedKey);
        SSTableReader.readRowSize(file, sstable.getDescriptor());
        return file;
    }

    private void readColumnFamily(SSTableReader sstable, FileDataInput file, SortedSet<byte[]> columnNames) throws IOException {
        BloomFilter bf = IndexHelper.defreezeBloomFilter(file);
        List<IndexHelper.IndexInfo> indexList = IndexHelper.deserializeIndex(file);

        // Deserialize ColumnFamily without columns
        cf = ColumnFamily.serializer().deserializeFromSSTableNoColumns(sstable.createColumnFamily(), file);

        List<byte[]> filteredColumnNames = filterColumnNames(bf, columnNames);
        if (filteredColumnNames.isEmpty()) {
            return;
        }

        if (indexList == null) {
            readSimpleColumns(file, columnNames, filteredColumnNames);
        } else {
            readIndexedColumns(sstable, file, columnNames, filteredColumnNames, indexList);
        }

        iter = cf.getSortedColumns().iterator();
    }

    private List<byte[]> filterColumnNames(BloomFilter bf, SortedSet<byte[]> columnNames) {
        List<byte[]> filteredColumnNames = new ArrayList<>(columnNames.size());
        for (byte[] name : columnNames) {
            if (bf.isPresent(name)) {
                filteredColumnNames.add(name);
            }
        }
        return filteredColumnNames;
    }

    private void closeFile(FileDataInput file) {
        if (file == null) return;

        try {
            file.close();
        } catch (IOException ioe) {
            logger.warn("Error closing " + file.getPath(), ioe);
        }
    }

    public DecoratedKey getKey() {
        return decoratedKey;
    }

    public ColumnFamily getColumnFamily() {
        return cf;
    }

    // Existing methods: readSimpleColumns(), readIndexedColumns() not shown for brevity.
}
